-- Behavioral boundary tests; synthetic data only.
\set ON_ERROR_STOP on
DO $$ BEGIN IF current_database()<>'wk_head_rh_permission_test' THEN RAISE EXCEPTION 'isolated fixture required'; END IF; END $$;
DO $test$ BEGIN IF EXISTS(SELECT 1 FROM workspaces w JOIN settings_test_before b USING(id) WHERE (w.payments_settings,w.nfse_settings,w.meeting_settings) IS DISTINCT FROM (b.payments_settings,b.nfse_settings,b.meeting_settings)) THEN RAISE EXCEPTION 'changed settings'; END IF; RAISE NOTICE 'SETTINGS PASS 1: migration preserves all settings'; END $test$;
DO $test$ BEGIN IF (SELECT count(*) FROM permissions WHERE resource IN('payments_settings','nfse_settings','meeting_settings'))<>6 THEN RAISE EXCEPTION 'catalog'; END IF; RAISE NOTICE 'SETTINGS PASS 2: six catalog keys registered'; END $test$;
RESET ROLE; SET ROLE authenticated; SELECT set_config('request.jwt.claim.sub','90000000-0000-4000-8000-000000000003',false); SELECT set_config('request.jwt.claims','{}',false);
DO $test$ BEGIN BEGIN PERFORM get_workspace_sensitive_settings('184b9435-0a9b-4334-9e89-8854dc883f5d','payments'); RAISE EXCEPTION 'Expected denial'; EXCEPTION WHEN insufficient_privilege THEN NULL; END; RAISE NOTICE 'SETTINGS PASS 3: payments member without configuration permission denied'; END $test$;
